create or replace function public.cadre_default_items() returns jsonb language sql immutable set search_path=public,pg_temp as $body$ select $items$[{"name": {"zh": "工作前人員出勤及機台分配確認", "en": "Confirmation of staff attendance and machine allocation before work", "vi": "Xác nhận tình hình đi làm của nhân viên và việc phân công máy trước khi làm việc"}, "standard": {"zh": "出勤狀況確認\n出勤率計算\n生產機台分配", "en": "CAttendance status confirmed\nAttendance calculation\nProduction machine allocation.", "vi": "Xác nhận tình hình đi làm của nhân viên\nTính tỷ lệ chuyên cần\nPhân công máy sản xuất"}, "id": 1}, {"name": {"zh": "工作前個人及共用的安全護具確認", "en": "Confirmation of personal and shared safety gear before work", "vi": "Xác nhận phương tiện bảo hộ cá nhân và phương tiện bảo hộ dùng chung trước khi làm việc"}, "standard": {"zh": "生產開始前確認所有技術員,耳塞,工作鞋是否具備,如沒有不准上機.\n共用安全護具,舉例安全帽,護目鏡是否具備", "en": "Before production starts, confirm that all technicians, earplugs, and work shoes are available. If not, do not allow the machine.\nShare safety protective equipment, such as helmets and goggles.", "vi": "Trước khi bắt đầu sản xuất, xác nhận tất cả kỹ thuật viên đã trang bị đầy đủ nút bịt tai và giày bảo hộ hay chưa. Nếu chưa đầy đủ thì không được phép vận hành máy.\nXác nhận có đầy đủ phương tiện bảo hộ dùng chung hay không, ví dụ như mũ bảo hộ và kính bảo hộ."}, "id": 2}, {"name": {"zh": "工作期間人員紀律確認", "en": "Confirmation of personnel discipline during work", "vi": "Xác nhận việc chấp hành kỷ luật của nhân viên trong thời gian làm việc"}, "standard": {"zh": "人員是否依照時間到休息區休息及抽菸區抽菸\n人員上班期間是否再規定生產區域,人員離開生產線是否落實申請", "en": "Whether the personnel smoke in the rest area and smoking area according to the time\nAre there any production areas during working hours? Are there any applications for leaving the production line?", "vi": "Nhân viên có nghỉ ngơi tại khu vực nghỉ và hút thuốc tại khu vực hút thuốc theo đúng thời gian quy định hay không.\nTrong giờ làm việc, nhân viên có ở trong khu vực sản xuất được quy định hay không; khi rời khỏi dây chuyền sản xuất có thực hiện thủ tục xin phép theo quy định hay không."}, "id": 3}, {"name": {"zh": "周邊設備運作狀況及點檢確認", "en": "Peripheral equipment operating status and inspection confirmation", "vi": "Xác nhận tình trạng vận hành và việc kiểm tra các thiết bị phụ trợ"}, "standard": {"zh": "周邊設備(空壓機、乾燥機、水塔…等)是否常運轉?機器日常點檢表是否落實執行?", "en": "Are the peripheral equipment (air compressor, dryer, water tower, etc.) in normal operation? Is the daily inspection form of the machine implemented?", "vi": "Các thiết bị phụ trợ như máy nén khí, máy sấy, tháp nước, v.v. có vận hành bình thường hay không? Bảng kiểm tra máy hằng ngày có được thực hiện đầy đủ hay không?"}, "id": 4}, {"name": {"zh": "機台運作狀況及點檢確認", "en": "Machine operation status and inspection confirmation", "vi": "Xác nhận tình trạng vận hành và việc kiểm tra máy móc"}, "standard": {"zh": "生產機器是否常運轉?機器日常點檢表 /預防保養紀錄表/設備維護履歷表暨故障修復時間統計表/停工後再生產確認表...等是否落實執行?", "en": "Are the production machines running normally? Are the daily inspection form/preventive maintenance record form/equipment maintenance resume form and fault repair time statistics form/stoppage resumption confirmation form, etc. implemented?", "vi": "Máy sản xuất có vận hành bình thường hay không? Các biểu mẫu như Bảng kiểm tra máy hằng ngày, Phiếu ghi chép bảo dưỡng phòng ngừa, Hồ sơ bảo trì thiết bị kiêm bảng thống kê thời gian sửa chữa sự cố, Phiếu xác nhận tái sản xuất sau khi ngừng sản xuất, v.v. có được thực hiện đầy đủ hay không?"}, "id": 5}, {"name": {"zh": "機台改機或調機結束後落實實施確認", "en": "Implementation confirmation after machine modification or adjustment", "vi": "Xác nhận các yêu cầu đã được thực hiện đầy đủ sau khi hoàn tất thay đổi máy hoặc điều chỉnh máy"}, "standard": {"zh": "機台改機或調機結束後，在機台連動生產前，落實淨空機台上、輸送帶、承接盒，檢查是否有殘留調機品及不良品。", "en": "After the machine is modified or adjusted, before the machine is put into production, the machine table, conveyor belt, and receiving box should be cleared to check whether there are any residual adjusted parts or defective parts.", "vi": "Sau khi hoàn tất thay đổi hoặc điều chỉnh máy, trước khi cho máy chạy liên động để sản xuất, phải dọn sạch bề mặt máy, băng tải và hộp tiếp nhận; đồng thời kiểm tra xem còn sót sản phẩm điều chỉnh máy hoặc sản phẩm không phù hợp hay không."}, "id": 6}, {"name": {"zh": "量儀器具及首件檢查落實實施確認", "en": "Implementation and confirmation of measuring instruments and first-article inspection", "vi": "Xác nhận việc sử dụng dụng cụ đo và kiểm tra sản phẩm đầu tiên đã được thực hiện đầy đủ"}, "standard": {"zh": "使用量具是否依照檢規上要求.量具是否再有效校驗日期內\n確認每機台早上首件檢驗是否落實量測及紀錄\n確認有沒有NG 尺寸沒有經核准還在生產", "en": "Whether the measuring tools used are i the inspection regulations and whether the measuring tools are within the valid calibration date\nConfirm whether the first part inspection of each machine in the morning is measured and recorded\nConfirm whether the NG size is still in production without approval", "vi": "Dụng cụ đo có được sử dụng theo yêu cầu trong quy phạm kiểm tra hay không? Dụng cụ đo có còn trong thời hạn hiệu chuẩn hay không?\nXác nhận việc đo và ghi chép kết quả kiểm tra sản phẩm đầu tiên vào buổi sáng của từng máy có được thực hiện đầy đủ hay không.\nXác nhận có tiếp tục sản xuất sản phẩm có kích thước NG khi chưa được phê duyệt hay không."}, "id": 7}, {"name": {"zh": "自主檢查表IPQC落實實施確認", "en": "Self-checklist IPQC implementation confirmation", "vi": "Xác nhận việc thực hiện Bảng tự kiểm tra và kiểm tra IPQC"}, "standard": {"zh": "確認每機台自主檢驗表是否落實量測及紀錄,使用量具是否依照檢規上要求.\n確認所有顧機人員是否知道每個尺寸檢驗頻率依據", "en": "Confirm whether the self-inspection form of each machine has been measured and recorded, and whether the measuring tools used are in accordance with the requirements of the inspection regulations.\nConfirm that all operator know the frequency of inspection for each dimension.", "vi": "Xác nhận việc đo và ghi chép trên Phiếu tự kiểm tra của từng máy có được thực hiện đầy đủ hay không; dụng cụ đo có được sử dụng theo yêu cầu trong quy phạm kiểm tra hay không.\nXác nhận tất cả nhân viên đứng máy có nắm rõ căn cứ quy định tần suất kiểm tra của từng kích thước hay không."}, "id": 8}, {"name": {"zh": "生產期間隨機抽測生產產品品質狀況確認", "en": "Random sampling during production to confirm product quality", "vi": "Xác nhận tình trạng chất lượng sản phẩm thông qua kiểm tra lấy mẫu ngẫu nhiên trong quá trình sản xuất"}, "standard": {"zh": "工作生產期間，隨機抽測生產產品品質狀況\n工作生產期間，隨機抽測機台是否依照BOM表資訊生產，如不符合要求立即停機，馬上檢討緣由，由相關人員評估確認後作決定。", "en": "During production, randomly test the quality of the products produced\nDuring production, we randomly test whether the machines are produced according to the BOM information. If they do not meet the requirements, we will immediately shut down the machine and review the reasons. The decision will be made after evaluation and confirmation by relevant personnel.", "vi": "Trong quá trình sản xuất, thực hiện kiểm tra lấy mẫu ngẫu nhiên để xác nhận tình trạng chất lượng sản phẩm.\nTrong quá trình sản xuất, kiểm tra ngẫu nhiên xem máy có sản xuất theo đúng thông tin trên bảng BOM hay không. Nếu không phù hợp yêu cầu, phải lập tức dừng máy và kiểm tra nguyên nhân; sau đó, người có liên quan đánh giá, xác nhận và đưa ra quyết định xử lý."}, "id": 9}, {"name": {"zh": "不良品隔離落實實施確認", "en": "Confirmation of the implementation of defective product isolation", "vi": "Xác nhận sản phẩm không phù hợp đã được cách ly đúng quy định"}, "standard": {"zh": "現場的不良品是否隔離?是否還有留在現場未移走?落實確認執行。", "en": "Have the defective products on site been isolated? Are there any left on site that have not been removed? Implement and confirm the execution.", "vi": "Sản phẩm không phù hợp tại hiện trường đã được cách ly hay chưa? Có còn sản phẩm không phù hợp lưu tại hiện trường mà chưa được di chuyển đi hay không? Phải kiểm tra và xác nhận việc thực hiện."}, "id": 10}, {"name": {"zh": "生產前製令單、BOM表、圖面確認", "en": "Confirmation of manufacturing order, BOM and drawings before production", "vi": "Xác nhận lệnh sản xuất, bảng BOM và bản vẽ trước khi sản xuất"}, "standard": {"zh": "在機台連動生產前，製令單、BOM表、圖面落實執行確認", "en": "Before the machine is put into production, the production order, BOM and drawings are confirmed.", "vi": "Trước khi cho máy chạy liên động để sản xuất, phải xác nhận Lệnh sản xuất, bảng BOM và bản vẽ đã được kiểm tra và áp dụng đầy đủ."}, "id": 11}, {"name": {"zh": "生產日報表、調機紀錄表及其他資料填寫落實實施確認", "en": "Fill out and confirm the daily production report, machine adjustment record and other materials", "vi": "Xác nhận Báo cáo sản xuất hằng ngày, Phiếu ghi chép điều chỉnh máy và các tài liệu khác đã được điền đầy đủ"}, "standard": {"zh": "生產日報表、調機紀錄表及其他資料填寫，落實執行確認\n生產日報表的停機時間、不良品數量及代碼是否落實填寫", "en": "Fill in the daily production report, machine adjustment record and other materials, and confirm the implementation\nWhether the downtime, number of defective products and codes in the daily production report are filled in", "vi": "Xác nhận Báo cáo sản xuất hằng ngày, Phiếu ghi chép điều chỉnh máy và các tài liệu khác đã được điền đầy đủ theo quy định.\nThời gian dừng máy, số lượng sản phẩm không phù hợp và mã lỗi trên Báo cáo sản xuất hằng ngày có được ghi đầy đủ hay không."}, "id": 12}, {"name": {"zh": "下班前工作檢查落實實施確認", "en": "Check and confirm the implementation of work before leaving get off work", "vi": "Xác nhận việc kiểm tra công việc trước khi tan ca đã được thực hiện đầy đủ"}, "standard": {"zh": "操作員是否依照規定時間關機,即離開生產線\n不良品紅色桶、橘色桶是否清理\n工具是否歸位", "en": "Whether the operator shuts down at the specified time, that is, leaves the production line\nAre the defective magenta and orange barrels cleaned?\nCheck whether the tool has put away", "vi": "Nhân viên vận hành có tắt máy theo đúng thời gian quy định trước khi rời khỏi dây chuyền sản xuất hay không.\nCác thùng màu đỏ và màu cam dùng để chứa sản phẩm không phù hợp đã được thu dọn hay chưa.\nDụng cụ đã được trả về đúng vị trí hay chưa."}, "id": 13}, {"name": {"zh": "5S整理、節能落實實施確認", "en": "5S cleaning and energy saving implementation confirmation", "vi": "Xác nhận việc thực hiện 5S và tiết kiệm năng lượng"}, "standard": {"zh": "機台四周及工作環境5S清潔確認\n工作結束，機台、周邊設備使用電源是否落實關閉", "en": "5S cleaning confirmation around the machine and working environment.\nAfter work, are the power supplies of the machine and peripheral equipment turned off?", "vi": "Xác nhận việc vệ sinh 5S khu vực xung quanh máy và môi trường làm việc.\nSau khi kết thúc công việc, xác nhận nguồn điện của máy và các thiết bị phụ trợ đã được tắt theo quy định hay chưa."}, "id": 14}, {"name": {"zh": "新人訓練考核內容落實實施確認", "en": "Implementation and confirmation of new employee training assessment content", "vi": "Xác nhận nội dung đào tạo và đánh giá nhân viên mới đã được thực hiện đầy đủ"}, "standard": {"zh": "新進人員對於產線產品的品質量測訓練及外觀判斷是否通過考核?如果沒通過考核，臨時對策要求1.值班人員針對該人員的品質，包含首件及IPQC檢驗，進行經常性復測。2.生產的桶號,製令卡需要貼有紅色豆型標簽來做確認。3.通知生產線人員及全檢包人員，接收到有貼紅色豆型標簽桶子，請落實執行加強確認品質,舉例漏加工...等。", "en": "Have the new employees passed the quality inspection training and appearance judgment of the production line products? If they have not passed the assessment, the temporary countermeasures require 1. The on-duty personnel shall conduct regular retests on the quality of the personnel, including first-piece and IPQC inspections. 2. The barrel number and the order card of the production need to be affixed with a red bean-shaped label for confirmation. 3. Notify the production line personnel and the full inspection and packaging personnel that if a barrel with a red bean-shaped label is received, please implement and strengthen the quality confirmation, give examples of missed processing, etc.", "vi": "Nhân viên mới đã vượt qua đánh giá về đào tạo đo kiểm chất lượng sản phẩm trên dây chuyền và khả năng nhận định ngoại quan hay chưa? Nếu chưa vượt qua đánh giá, phải áp dụng các biện pháp tạm thời sau:\n1. Nhân viên trực ca phải thường xuyên đo kiểm lại chất lượng sản phẩm do nhân viên đó phụ trách, bao gồm kiểm tra sản phẩm đầu tiên và kiểm tra IPQC.\n2. Thùng sản phẩm và thẻ Lệnh sản xuất phải được dán nhãn đỏ hình hạt đậu để nhận biết.\n3. Thông báo cho nhân viên dây chuyền sản xuất và nhân viên kiểm tra 100%, đóng gói rằng khi tiếp nhận thùng có dán nhãn đỏ hình hạt đậu, phải tăng cường kiểm tra chất lượng, ví dụ như tình trạng bỏ sót công đoạn gia công, v.v."}, "id": 15}, {"name": {"zh": "品異及客訴改善防堵落實實施確認", "en": "Implementation and confirmation of product defects and customer complaints improvement and prevention", "vi": "Xác nhận các biện pháp cải thiện và phòng ngừa tái diễn đối với bất thường chất lượng và khiếu nại của khách hàng đã được thực hiện đầy đủ"}, "standard": {"zh": "品異及客訴問題，是否找出真因?組內全部人員是否都知悉?後續改善、防堵是否落實執行確認", "en": "Have you found the real cause of product defects and customer complaints? Are all team members aware of them? Have you implemented and confirmed the follow-up improvements and prevention measures?", "vi": "Đối với các vấn đề bất thường về chất lượng và khiếu nại của khách hàng, đã xác định được nguyên nhân gốc rễ hay chưa? Toàn bộ nhân viên trong tổ đã được thông báo và nắm rõ hay chưa? Các biện pháp cải thiện và phòng ngừa tái diễn sau đó có được thực hiện đầy đủ hay không?"}, "id": 16}]$items$::jsonb $body$;
revoke all on function public.cadre_default_items() from public,anon,authenticated;
grant execute on function public.cadre_default_items() to service_role;
-- Template snapshots preserve historical meanings when department items change.
create table public.cadre_month_templates (
 country_code text not null check(country_code in ('TW','VM','MX')),
 department_id uuid not null references public.departments(id),
 month_date date not null check(extract(day from month_date)=1),
 items jsonb not null, revision integer not null default 1,
 updated_by uuid not null references public.operator_accounts(id), updated_at timestamptz not null default now(),
 primary key(country_code,department_id,month_date)
);
alter table public.cadre_month_templates enable row level security;
revoke all on public.cadre_month_templates from public,anon,authenticated;
grant all on public.cadre_month_templates to service_role;
alter table public.cadre_daily_records add column template_snapshot jsonb;
update public.cadre_daily_records set template_snapshot=public.cadre_default_items();
alter table public.cadre_daily_records alter column template_snapshot set not null;
alter table public.cadre_daily_records drop constraint cadre_daily_records_results_check;
alter table public.cadre_daily_records add constraint cadre_results_count check(jsonb_typeof(results)='array' and jsonb_array_length(results) between 1 and 200);

create or replace function public.save_cadre_template(p_country text,p_department uuid,p_month date,p_account uuid,p_revision integer,p_items jsonb)
returns jsonb language plpgsql security invoker set search_path=public,pg_temp as $$
declare u record; prior public.cadre_month_templates; saved public.cadre_month_templates; v jsonb; i integer;
begin
 select role,department_id,is_active into u from operator_accounts where id=p_account;
 if not found or not u.is_active or u.role not in ('admin','supervisor') or (u.role<>'admin' and u.department_id is distinct from p_department) then raise exception 'forbidden'; end if;
 if not exists(select 1 from departments where id=p_department and country_code=p_country and is_active) then raise exception 'invalid_department'; end if;
 if p_month is null or extract(day from p_month)<>1 or p_month<date '2000-01-01' or p_month>date '2099-12-01' or p_revision is null or p_revision<0 or jsonb_typeof(p_items) is distinct from 'array' then raise exception 'invalid_template'; end if;
 if jsonb_array_length(p_items) not between 1 and 200 then raise exception 'invalid_template'; end if;
 for i in 0..jsonb_array_length(p_items)-1 loop
  v:=p_items->i;
  if v->>'id' is distinct from (i+1)::text or jsonb_typeof(v->'name') is distinct from 'object' or jsonb_typeof(v->'standard') is distinct from 'object' or length(coalesce(v->'name'->>'zh','')) not between 1 and 500 or length(coalesce(v->'standard'->>'zh','')) not between 1 and 5000 or length(v::text)>30000 then raise exception 'invalid_template'; end if;
 end loop;
 perform pg_advisory_xact_lock(hashtextextended('cadre-template:'||p_country||':'||p_department||':'||p_month,0));
 select * into prior from cadre_month_templates where country_code=p_country and department_id=p_department and month_date=p_month for update;
 if coalesce(prior.revision,0)<>p_revision then raise exception 'record_changed'; end if;
 if jsonb_array_length(p_items)<jsonb_array_length(coalesce(prior.items,public.cadre_default_items())) then raise exception 'cannot_remove_items'; end if;
 insert into cadre_month_templates(country_code,department_id,month_date,items,revision,updated_by)
 values(p_country,p_department,p_month,p_items,coalesce(prior.revision,0)+1,p_account)
 on conflict(country_code,department_id,month_date) do update set items=excluded.items,revision=excluded.revision,updated_by=p_account,updated_at=now() returning * into saved;
 insert into audit_logs(account_id,action,entity_type,entity_id,payload,country_code) values(p_account,'cadre_template_save','department',p_department,jsonb_build_object('before',to_jsonb(prior),'after',to_jsonb(saved)),p_country);
 return to_jsonb(saved);
end $$;
revoke all on function public.save_cadre_template(text,uuid,date,uuid,integer,jsonb) from public,anon,authenticated;
grant execute on function public.save_cadre_template(text,uuid,date,uuid,integer,jsonb) to service_role;

create or replace function public.save_cadre_daily_v2(p_country text,p_department uuid,p_date date,p_account uuid,p_revision integer,p_results jsonb,p_duty text,p_supervisor text,p_confirm boolean,p_template_revision integer)
returns jsonb language plpgsql security invoker set search_path=public,pg_temp as $$
declare u record; prior public.cadre_daily_records; saved public.cadre_daily_records; tmpl public.cadre_month_templates; items jsonb; v jsonb; i integer; m date:=date_trunc('month',p_date)::date;
begin
 select role,department_id,is_active into u from operator_accounts where id=p_account;
 if not found or not u.is_active or u.role not in ('admin','supervisor') or (u.role<>'admin' and u.department_id is distinct from p_department) then raise exception 'forbidden'; end if;
 if not exists(select 1 from departments where id=p_department and country_code=p_country and is_active) then raise exception 'invalid_department'; end if;
 if p_date is null or p_date>(now() at time zone 'Asia/Taipei')::date or p_date<date '2000-01-01' or p_revision is null or p_revision<0 or jsonb_typeof(p_results) is distinct from 'array' or p_duty is null or length(btrim(p_duty)) not between 1 and 100 or p_supervisor is null or length(p_supervisor)>100 or p_confirm is null then raise exception 'invalid_cadre_record'; end if;
 perform pg_advisory_xact_lock(hashtextextended('cadre-template:'||p_country||':'||p_department||':'||m,0));
 perform pg_advisory_xact_lock(hashtextextended('cadre:'||p_country||':'||p_department||':'||p_date,0));
 select * into tmpl from cadre_month_templates where country_code=p_country and department_id=p_department and month_date=m;
 select * into prior from cadre_daily_records where country_code=p_country and department_id=p_department and inspection_date=p_date for update;
 if coalesce(prior.revision,0)<>p_revision then raise exception 'record_changed'; end if;
 if prior.id is null and coalesce(tmpl.revision,0) is distinct from p_template_revision then raise exception 'record_changed'; end if;
 items:=coalesce(prior.template_snapshot,tmpl.items,public.cadre_default_items());
 if jsonb_array_length(p_results)<>jsonb_array_length(items) then raise exception 'invalid_cadre_record'; end if;
 for i in 0..jsonb_array_length(items)-1 loop
  v:=p_results->i;
  if v->>'id' is distinct from items->i->>'id' or jsonb_typeof(v->'value') is distinct from 'string' or v->>'value' not in ('','V','∖','Φ','N/A') or jsonb_typeof(v->'note') is distinct from 'string' or length(v->>'note')>2000 then raise exception 'invalid_cadre_record'; end if;
  if v->>'value'='Φ' and coalesce(prior.results->i->>'value','') not in ('∖','Φ') then raise exception 'improvement_requires_issue'; end if;
  if p_confirm and (v->>'value'='' or length(btrim(p_supervisor))=0) then raise exception 'confirmation_incomplete'; end if;
 end loop;
 insert into cadre_daily_records(country_code,department_id,inspection_date,results,template_snapshot,duty_name,supervisor_name,confirmed_at,updated_by,revision)
 values(p_country,p_department,p_date,p_results,items,btrim(p_duty),case when p_confirm then btrim(p_supervisor) else '' end,case when p_confirm then now() end,p_account,coalesce(prior.revision,0)+1)
 on conflict(country_code,department_id,inspection_date) do update set results=excluded.results,duty_name=excluded.duty_name,supervisor_name=excluded.supervisor_name,confirmed_at=excluded.confirmed_at,updated_by=p_account,updated_at=now(),revision=excluded.revision returning * into saved;
 insert into audit_logs(account_id,action,entity_type,entity_id,payload,country_code) values(p_account,'cadre_daily_save','cadre_daily_record',saved.id,jsonb_build_object('before',to_jsonb(prior),'after',to_jsonb(saved)),p_country);
 return to_jsonb(saved);
end $$;
revoke all on function public.save_cadre_daily_v2(text,uuid,date,uuid,integer,jsonb,text,text,boolean,integer) from public,anon,authenticated;
grant execute on function public.save_cadre_daily_v2(text,uuid,date,uuid,integer,jsonb,text,text,boolean,integer) to service_role;
-- Retire the fixed-16 writer so an old browser cannot bypass template revision checks.
revoke execute on function public.save_cadre_daily(text,uuid,date,uuid,integer,jsonb,text,text,boolean) from service_role;

create table public.crane_inspection_records (
 id uuid primary key default gen_random_uuid(), country_code text not null check(country_code in ('TW','VM','MX')),
 department_id uuid not null references departments(id), equipment_id uuid not null references equipments(id),
 kind text not null check(kind in ('monthly','daily')), period_date date not null, inspection_date date not null,
 equipment_snapshot jsonb not null, results jsonb not null, details jsonb not null,
 inspector_name text not null, leader_name text not null default '', supervisor_name text not null default '',
 completed boolean not null default false, confirmed_at timestamptz,
 revision integer not null default 1, updated_by uuid not null references operator_accounts(id), updated_at timestamptz not null default now(),
 unique(country_code,equipment_id,kind,period_date)
);
alter table public.crane_inspection_records enable row level security;
revoke all on public.crane_inspection_records from public,anon,authenticated;
grant all on public.crane_inspection_records to service_role;
create index crane_department_month on public.crane_inspection_records(country_code,department_id,period_date);
create or replace function public.save_crane_record(p_country text,p_account uuid,p_equipment uuid,p_kind text,p_date date,p_revision integer,p_results jsonb,p_details jsonb,p_inspector text,p_leader text,p_supervisor text,p_completed boolean,p_confirm boolean)
returns jsonb language plpgsql security invoker set search_path=public,pg_temp as $$
declare u record; eq record; prior public.crane_inspection_records; saved public.crane_inspection_records; period date; i integer; v jsonb; expected integer;
begin
 select role,department_id,is_active into u from operator_accounts where id=p_account;
 if not found or not u.is_active or u.role not in ('admin','supervisor','operator') then raise exception 'forbidden'; end if;
 select e.*,g.name_zh as group_name into eq from equipments e left join equipment_groups g on g.id=e.equipment_group_id where e.id=p_equipment and e.country_code=p_country and e.archived_at is null for share of e;
 if not found or (u.role<>'admin' and u.department_id is distinct from eq.department_id) then raise exception 'forbidden'; end if;
 if not exists(select 1 from departments where id=eq.department_id and country_code=p_country and is_active) or length(btrim(eq.machine_no))=0 or (eq.name_zh||' '||coalesce(eq.group_name,'')) !~ '(天車|起重機)' then raise exception 'invalid_crane'; end if;
 if p_kind is null or p_kind not in ('monthly','daily') or p_date is null or p_date<date '2000-01-01' or p_date>(now() at time zone 'Asia/Taipei')::date or p_revision is null or p_revision<0 or jsonb_typeof(p_results) is distinct from 'array' or jsonb_typeof(p_details) is distinct from 'object' or length(p_details::text)>25000 or p_inspector is null or length(btrim(p_inspector)) not between 1 and 100 or p_leader is null or length(p_leader)>100 or p_supervisor is null or length(p_supervisor)>100 or p_completed is null or p_confirm is null then raise exception 'invalid_crane_record'; end if;
 if u.role='operator' and (p_confirm or p_supervisor<>'' or p_leader<>'') then raise exception 'forbidden'; end if;
 expected:=case when p_kind='monthly' then 22 else 6 end;
 if jsonb_array_length(p_results)<>expected then raise exception 'invalid_crane_record'; end if;
 if p_details - array['model','capacity','location','hazard','risk','measures','suitability'] <> '{}'::jsonb then raise exception 'invalid_crane_record'; end if;
 for v in select value from jsonb_each(p_details) loop
  if jsonb_typeof(v) is distinct from 'string' or length(v#>>'{}')>3000 then raise exception 'invalid_crane_record'; end if;
 end loop;
 for i in 0..expected-1 loop
  v:=p_results->i;
  if v->>'id' is distinct from (i+1)::text or jsonb_typeof(v->'value') is distinct from 'string' or (p_kind='monthly' and v->>'value' not in ('','X','Δ','✔','─')) or (p_kind='daily' and v->>'value' not in ('','ˇ','×')) then raise exception 'invalid_crane_record'; end if;
  if p_completed and v->>'value'='' then raise exception 'confirmation_incomplete'; end if;
 end loop;
 if p_confirm and (not p_completed or length(btrim(p_supervisor))=0) then raise exception 'confirmation_incomplete'; end if;
 period:=case when p_kind='monthly' then date_trunc('month',p_date)::date else p_date end;
 perform pg_advisory_xact_lock(hashtextextended('crane:'||p_country||':'||p_equipment||':'||p_kind||':'||period,0));
 select * into prior from crane_inspection_records where country_code=p_country and equipment_id=p_equipment and kind=p_kind and period_date=period for update;
 if coalesce(prior.revision,0)<>p_revision then raise exception 'record_changed'; end if;
 if prior.id is not null and prior.department_id<>eq.department_id then raise exception 'equipment_changed'; end if;
 insert into crane_inspection_records(country_code,department_id,equipment_id,kind,period_date,inspection_date,equipment_snapshot,results,details,inspector_name,leader_name,supervisor_name,completed,confirmed_at,revision,updated_by)
 values(p_country,eq.department_id,p_equipment,p_kind,period,p_date,coalesce(prior.equipment_snapshot,jsonb_build_object('machine_no',eq.machine_no,'property_no',eq.property_no,'name_zh',eq.name_zh)),p_results,p_details,btrim(p_inspector),btrim(p_leader),case when p_confirm then btrim(p_supervisor) else '' end,p_completed,case when p_confirm then now() end,coalesce(prior.revision,0)+1,p_account)
 on conflict(country_code,equipment_id,kind,period_date) do update set inspection_date=excluded.inspection_date,results=excluded.results,details=excluded.details,inspector_name=excluded.inspector_name,leader_name=excluded.leader_name,supervisor_name=excluded.supervisor_name,completed=excluded.completed,confirmed_at=excluded.confirmed_at,revision=excluded.revision,updated_by=p_account,updated_at=now() returning * into saved;
 insert into audit_logs(account_id,action,entity_type,entity_id,payload,country_code) values(p_account,'crane_record_save','crane_inspection_record',saved.id,jsonb_build_object('before',to_jsonb(prior),'after',to_jsonb(saved)),p_country);
 return to_jsonb(saved);
end $$;
revoke all on function public.save_crane_record(text,uuid,uuid,text,date,integer,jsonb,jsonb,text,text,text,boolean,boolean) from public,anon,authenticated;
grant execute on function public.save_crane_record(text,uuid,uuid,text,date,integer,jsonb,jsonb,text,text,text,boolean,boolean) to service_role;
